[Hookable(false)]
public void setControls()
{
    next setControls();
    if (globalUnifiedPricingEnabled)
    {
        Common argsRecord = this.args().record();

        if (activeRecId != argsRecord.RecId)
        {
            QueryBuildDataSource qbds = GUPMarginComponentAdjustmentHistory_ds.query().dataSourceTable(tableNum(GUPMarginComponentAdjustmentHistory));

            qbds.rangeField(fieldNum(GUPMarginComponentAdjustmentHistory, InventTransId))
                .value(queryValue(mcrPriceHistoryForm.getInventTransId()));

            GUPMarginComponentAdjustmentHistory_ds.executeQuery();
        }
    }
}
